//! What the Tilo fleet's signed manifests say about each app, compiled in,
//! so an app that is not on this device yet is known as fully as one that
//! is. Generated by `tools/apps/generate_catalogue_fleet.py`.

/// An action an app offers while closed (`[[offers]]`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FleetAction {
    pub resource: &'static str,
    pub action: &'static str,
    pub label: &'static str,
    /// Empty when the manifest gives none.
    pub description: &'static str,
}

/// One Tilo app's manifest metadata.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FleetApp {
    pub id: &'static str,
    /// The registry's tag line; empty when it has none.
    pub tagline: &'static str,
    /// Its name in other languages (`[package.names]`).
    pub names: &'static [&'static str],
    /// Every language's `search-keywords`.
    pub keywords: &'static [&'static str],
    /// `(kind, label)` of each document it creates.
    pub resource_types: &'static [(&'static str, &'static str)],
    pub actions: &'static [FleetAction],
}

#[path = "fleet_generated.rs"]
mod generated;

#[must_use]
pub fn apps() -> &'static [FleetApp] {
    generated::APPS
}

/// The fleet's metadata for `package_id`. A development build publishes the
/// same apps under `dev.tilo.`, which resolve to their `so.tilo.` entry.
#[must_use]
pub fn metadata(package_id: &str) -> Option<&'static FleetApp> {
    let canonical = package_id
        .strip_prefix("dev.tilo.")
        .map(|name| format!("so.tilo.{name}"));
    let wanted = canonical.as_deref().unwrap_or(package_id);
    apps().iter().find(|app| app.id == wanted)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_fleet_knows_documents_and_closed_actions() {
        let sheets = metadata("so.tilo.sheets").expect("Sheets is in the fleet");
        assert!(
            sheets
                .resource_types
                .contains(&("sheets.workbook", "Workbook"))
        );
        assert!(!sheets.tagline.is_empty());
        assert!(sheets.keywords.contains(&"spreadsheet"));
        assert_eq!(
            metadata("dev.tilo.sheets").map(|app| app.id),
            Some("so.tilo.sheets")
        );
        let calendar = metadata("so.tilo.calendar").expect("Calendar is in the fleet");
        assert!(
            calendar
                .actions
                .iter()
                .any(|action| action.action == "show-tasks")
        );
    }
}
